// Import the attributes used to validate and shape the database columns.
using System.ComponentModel.DataAnnotations;
using System.ComponentModel.DataAnnotations.Schema;

namespace WebApplication1.models;

// Entity that represents one blood donation candidate.
public class DCandidate
{
    // Primary key generated by SQL Server.
    [Key]
    public int id { get; set; }

    // Full name is required and limited to the configured column size.
    [Required]
    [StringLength(100, MinimumLength = 2)]
    [Column(TypeName = "nvarchar(100)")]
    public string fullName { get; set; } = string.Empty;

    // Email is required, must be a valid address and fit the column.
    [Required]
    [EmailAddress]
    [StringLength(100)]
    [Column(TypeName = "nvarchar(100)")]
    public string email { get; set; } = string.Empty;

    // Age must be a realistic value for a donor.
    [Range(1, 120)]
    public int age { get; set; }

    // Blood group must be one of the eight recognised values.
    [Required]
    [RegularExpression("^(A|B|AB|O)[+-]$", ErrorMessage = "Blood group must be one of A+, A-, B+, B-, AB+, AB-, O+ or O-.")]
    [Column(TypeName = "nvarchar(3)")]
    public string bloodGroup { get; set; } = string.Empty;

    // Mobile number is required and checked against a phone number pattern.
    [Required]
    [Phone]
    [StringLength(100)]
    [Column(TypeName = "nvarchar(100)")]
    public string mobile { get; set; } = string.Empty;

    // Street address is optional but limited to the column size.
    [StringLength(100)]
    [Column(TypeName = "nvarchar(100)")]
    public string address { get; set; } = string.Empty;
}
